((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"id":"2016-2","year":2016,"grades":[2],"label":"2 класс","tasksUrl":"assets/kenguru/kenguru_2016_class_2.pdf","answersUrl":"assets/kenguru/kenguru_2016_answers.pdf","solutionUrl":null,"answerLetters":"АБВГД","cards":[{"number":1,"title":"Буквы слова КЕНГА","question":"Какой буквы из слова КЕНГА нет на рисунке справа?","options":[{"text":"К"},{"text":"Е"},{"text":"Н"},{"text":"Г"},{"text":"А"}],"condition":{"src":"assets/grades-2/2016/task-01.svg","width":306,"height":164,"alt":"Три ряда букв. Сверху М, У, Ш, Н, С. Посередине А, Л, О, Е. Снизу Р, К, Т, В."},"answer":3,"points":3,"review":[{"title":"Выпишем буквы из слова","text":"В слове КЕНГА пять букв: К, Е, Н, Г и А."},{"title":"Найдём их на рисунке","text":"Н есть в верхнем ряду, А и Е в среднем, К в нижнем. Буквы Г нет ни в одном ряду."}],"keyNote":null},{"number":2,"title":"День рождения Крошки Ру","question":"Крошка Ру сегодня отмечает 1 год и 3 месяца. Через сколько месяцев ему будет 2 года?","options":[{"text":"3"},{"text":"5"},{"text":"7"},{"text":"8"},{"text":"9"}],"condition":null,"answer":4,"points":3,"review":[{"title":"Посчитаем месяцы в году","text":"От первого до второго дня рождения проходит 12 месяцев. После первого уже прошло три месяца."},{"title":"Найдём оставшееся время","text":"До второго дня рождения ещё 12 − 3 = 9 месяцев."}],"keyNote":null},{"number":3,"title":"Переплетённые верёвочки","question":"Сколько веревочек изображено на рисунке?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":{"src":"assets/grades-2/2016/task-03.svg","width":277,"height":192,"alt":"Переплетённые верёвки с шестью свободными концами."},"answer":2,"points":3,"review":[{"title":"Найдём свободные концы","text":"Пересечения не означают, что верёвочки связаны. Проследим ветви через пересечения и отметим шесть настоящих концов, за пределами которых линия не продолжается."},{"title":"Соединим концы попарно","text":"Если пройти по каждому шнуру от одного конца до другого, получаются три отдельные пары, и замкнутого кольца не остаётся. Значит, верёвочек три."}],"keyNote":null},{"number":4,"title":"Дождь и солнце","question":"В Тридевятом царстве погода меняется каждый день: день идет дождь, день светит солнце. Сколько солнечных дней будет в неделе, которая началась дождливым понедельником?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Отметим понедельник","text":"В понедельник дождь, поэтому во вторник солнце. Дальше погода снова меняется каждый день."},{"title":"Посчитаем солнечные дни","text":"Солнце светит во вторник, четверг и субботу. Это три дня."}],"keyNote":null},{"number":5,"title":"Точки в круглом лабиринте","question":"В какую из точек лабиринта можно попасть из точки O?","options":[{"text":"А"},{"text":"Б"},{"text":"В"},{"text":"Г"},{"text":"Д"}],"condition":{"src":"assets/grades-2/2016/task-05.svg","width":254,"height":254,"alt":"Круглый лабиринт. O находится ближе к центру. А снаружи сверху, Б снаружи снизу справа, В снаружи снизу слева. Г и Д отмечены во внутренних проходах."},"answer":0,"points":3,"review":[{"title":"Выйдем из центра","text":"От О идём через разрыв слева сверху. К следующему кольцу проходим через щель в верхней части, затем идём налево через разрыв внешнего прохода."},{"title":"Проследим внешний проход","text":"Из него можно подняться к А. Поперечные стенки не пускают к Б и В. Внутренние ответвления с точками Г и Д отделены стенками от этого маршрута. Доступна только А."}],"keyNote":null},{"number":6,"title":"Цифры 2016 года","question":"Ближайший год, в записи которого будут те же 4 цифры, что и в 2016 году, — это","options":[{"text":"1206"},{"text":"2106"},{"text":"2601"},{"text":"2061"},{"text":"2026"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Сохраним начало года","text":"Из тех же цифр получить ближайший более поздний год можно, сохранив первые две цифры 20. Тогда для конца остаются 1 и 6."},{"title":"Поменяем последние две цифры","text":"Порядок 16 уже даёт 2016, а порядок 61 даёт 2061. Годы с изменённой второй цифрой, которая была нулём, наступят позднее. Ответ — 2061."}],"keyNote":null},{"number":7,"title":"Квартира и этаж","question":"У подъезда висит табличка (см. рисунок). На каком этаже находится квартира с номером 27?\n\n1 этаж — 15–19\n2 этаж — 20–24\n3 этаж — 25–29\n4 этаж — 30–34\n5 этаж — 35–39","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Найдём нужный ряд","text":"Номер 27 находится между 25 и 29. Эти номера стоят в одной строке таблички."},{"title":"Прочитаем этаж","text":"Диапазону от 25 до 29 соответствует третий этаж. Там находится квартира 27."}],"keyNote":null},{"number":8,"title":"Десятки и единицы","question":"В каком из этих чисел цифра десятков в два раза больше, чем цифра единиц?","options":[{"text":"124"},{"text":"424"},{"text":"753"},{"text":"263"},{"text":"135"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Сравним последние две цифры","text":"В 124 и 424 десятков 2, единиц 4, а нужно наоборот, чтобы цифра десятков была больше. В 753 удвоенная тройка даёт 6, а не 5. В 135 десятков 3 и единиц 5."},{"title":"Проверим 263","text":"Единиц 3, десятков 6. Поскольку 6 = 2 · 3, подходит 263."}],"keyNote":null},{"number":9,"title":"Прыжки Кузи и Пузи","question":"Два кенгуренка Кузя и Пузя прыгают по клеточкам навстречу друг другу (см. рисунок). Они прыгают одновременно, но Кузя прыгает на соседнюю клеточку, а Пузя — через одну клеточку. На какой клеточке они встретятся?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":{"src":"assets/grades-2/2016/task-09.svg","width":755,"height":97,"alt":"Полоска из 13 клеток. Кузя стоит в первой слева, Пузя в последней. Номера 1, 2, 3, 4, 5 написаны в клетках с третьей по седьмую слева."},"answer":2,"points":3,"review":[{"title":"Посчитаем общий шаг","text":"За один прыжок Кузя проходит одну клетку, Пузя две. Вместе они сокращают расстояние на три клетки."},{"title":"Найдём встречу","text":"Между стартовыми клетками 12 шагов, поэтому они встретятся после четырёх прыжков. От старта Кузи это пятая клетка слева. На ней написано 3."}],"keyNote":null},{"number":10,"title":"Таблички вдоль дорожки","question":"По разные стороны дорожки стоят таблички с буквами (см. рисунок). Маша прошла по этой дорожке из точки 1 в точку 2 и прочитала только то, что видела справа от себя. Что у нее получилось?","options":[{"text":"КГРУ"},{"text":"КЕНР"},{"text":"КНУ"},{"text":"КНГР"},{"text":"КНУР"}],"condition":{"src":"assets/grades-2/2016/task-10.svg","width":292,"height":248,"alt":"Из точки 1 дорожка идёт вверх, табличка К справа. Затем дорожка поворачивает влево, Н над ней, Е под ней. На следующем спуске У слева и Г справа. Внизу дорога идёт направо, табличка Р под ней. Затем дорога поворачивает вверх, влево и вниз к точке 2. На коротком подъёме ещё одна У слева на рисунке."},"answer":4,"points":3,"review":[{"title":"Пойдём от точки 1","text":"На первом подъёме справа К. Повернув влево, Маша видит справа Н: оно выше дорожки на рисунке."},{"title":"Проследим следующие повороты","text":"На спуске справа от Маши находится У слева от дорожки на рисунке. Когда она пойдёт вправо, под дорожкой будет Р. Вторая У на подъёме окажется слева от Маши. Получится КНУР."}],"keyNote":null},{"number":11,"title":"Разность двузначных чисел","question":"Если из самого большого двузначного числа вычесть самое маленькое двузначное число, то получится","options":[{"text":"88"},{"text":"89"},{"text":"90"},{"text":"91"},{"text":"99"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Найдём крайние числа","text":"Самое маленькое двузначное число — 10, самое большое — 99."},{"title":"Вычтем меньшее","text":"Из 99 вычитаем 10. Получаем 89."}],"keyNote":null},{"number":12,"title":"Карточки в квадратной коробке","question":"Четыре карточки, изображенные справа, уложили в квадратную коробку с белым дном. Что могло получиться?","options":[{"image":"assets/grades-2/2016/task-12-answer-1.svg","description":"Квадрат из трёх закрашенных треугольников, двух полосатых и трёх белых"},{"image":"assets/grades-2/2016/task-12-answer-2.svg","description":"Диагональные треугольники в каждой четверти, полосатые по бокам"},{"image":"assets/grades-2/2016/task-12-answer-3.svg","description":"Серые полосы у верхних боковых краёв, полосатые углы снизу"},{"image":"assets/grades-2/2016/task-12-answer-4.svg","description":"Серый треугольник в двух противоположных углах и два полосатых вдоль левой стороны"},{"image":"assets/grades-2/2016/task-12-answer-5.svg","description":"Два серых квадрата по диагонали. Два полосатых треугольника в других четвертях"}],"condition":{"src":"assets/grades-2/2016/task-12.svg","width":420,"height":91,"alt":"Две одинаковые серые квадратные карточки и две одинаковые полосатые треугольные, каждая в форме половины квадрата."},"answer":4,"points":4,"review":[{"title":"Разместим два квадрата","text":"На рисунке Д поставим серые квадраты по диагонали: в левый верхний и правый нижний углы коробки. Они занимают по одной четверти дна."},{"title":"Добавим треугольные карточки","text":"В двух свободных четвертях уложим полосатые треугольники. В каждой четверти одна половина закроется, а другая покажет белое дно. Получится рисунок Д."}],"keyNote":null},{"number":13,"title":"Время до полуночи","question":"Сколько времени остается до полуночи, если сейчас половина девятого вечера?","options":[{"text":"210 минут"},{"text":"180 минут"},{"text":"150 минут"},{"text":"120 минут"},{"text":"90 минут"}],"condition":null,"answer":0,"points":4,"review":[{"title":"Прочитаем время","text":"Половина девятого вечера — это 20:30. До 21:00 остаётся 30 минут."},{"title":"Досчитаем до полуночи","text":"От 21:00 до полуночи ещё три часа, или 180 минут. Вместе 180 + 30 = 210 минут."}],"keyNote":null},{"number":14,"title":"Свет в окнах","question":"В доме 12 комнат, и в каждой комнате по два окна. Вечером был виден свет в 18 окнах. В скольких комнатах свет не был включен?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Посчитаем тёмные окна","text":"Всего в доме 12 · 2 = 24 окна. Из них 18 освещены, значит, 24 − 18 = 6 тёмных."},{"title":"Сгруппируем окна по комнатам","text":"Одна комната без света даёт два тёмных окна. Шесть окон — это 6 : 2 = 3 комнаты."}],"keyNote":null},{"number":15,"title":"Квадрат из квадратиков","question":"Женя сначала нарисовала 4 маленьких квадратика (см. рисунок). Потом она пририсовала к ним еще несколько таких же квадратиков так, что получился большой квадрат. Сколько квадратиков она могла дорисовать?","options":[{"text":"2"},{"text":"4"},{"text":"5"},{"text":"6"},{"text":"7"}],"condition":{"src":"assets/grades-2/2016/task-15.svg","width":137,"height":97,"alt":"Три квадратика в горизонтальном ряду и ещё один над левым."},"answer":2,"points":4,"review":[{"title":"Измерим ширину рисунка","text":"Три квадратика уже стоят в одном ряду. Дорисуем над ними недостающие квадратики, чтобы сделать три ряда по три."},{"title":"Сравним с вариантами","text":"В квадрате 3 × 3 девять клеток. Четыре уже есть, не хватает 9 − 4 = 5. При остальных числах из вариантов общее число клеток не даёт квадрат."}],"keyNote":null},{"number":16,"title":"Два числа подряд","question":"Сумма двух идущих подряд чисел равна 21. Чему равно их произведение?","options":[{"text":"22"},{"text":"80"},{"text":"90"},{"text":"100"},{"text":"110"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Найдём два соседних числа","text":"Две десятки в сумме дают 20. Если ко второй десятке прибавить 1, получаются соседние числа 10 и 11 с суммой 21."},{"title":"Перемножим","text":"10 · 11 = 110."}],"keyNote":null},{"number":17,"title":"Колючки кактуса","question":"У ребристого колючего кактуса 8 ребер, и на каждом ребре растет по 6 или по 7 колючек (см. рисунок). Ребра с шестью и с семью колючками чередуются. Сколько колючек не видно на рисунке?","options":[{"text":"18"},{"text":"19"},{"text":"20"},{"text":"21"},{"text":"26"}],"condition":{"src":"assets/grades-2/2016/task-17.svg","width":176,"height":254,"alt":"На передней стороне кактуса видно пять рёбер. На них по порядку 7, 6, 7, 6 и 7 колючек."},"answer":1,"points":4,"review":[{"title":"Посмотрим на чередование","text":"На пяти видимых рёбрах колючек 7, 6, 7, 6 и 7. По кругу восемь рёбер, поэтому после последней видимой семёрки придутся 6, 7 и 6."},{"title":"Сложим невидимые колючки","text":"На трёх невидимых рёбрах всего 6 + 7 + 6 = 19 колючек."}],"keyNote":null},{"number":18,"title":"Воскресенья в лагере","question":"Оля уехала в лагерь на 25 дней. По воскресениям к ней приезжала мама. Какое самое большое число раз мама могла к ней приезжать?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Отметим воскресенья по порядку","text":"Между воскресеньями семь дней. Если первый день лагеря воскресенье, визиты будут в дни 1, 8, 15 и 22."},{"title":"Проверим пятый визит","text":"Следующее воскресенье пришлось бы на 29-й день. Даже при самом раннем первом визите это позднее 25-го. Максимум — четыре визита."}],"keyNote":null},{"number":19,"title":"Код пещеры","question":"Маленький гном забыл код замка от двери в свою пещеру. Он помнит, что код состоит из четырех цифр 1, 2, 3, 4, и уже попробовал 4 варианта: 3421, 4123, 3214, 2134, но все они не подошли. Найдите правильный код, если известно, что каждую цифру гном поставил на нужное место два раза.","options":[{"text":"4321"},{"text":"3124"},{"text":"3142"},{"text":"2143"},{"text":"1324"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Запишем попытки друг под другом","text":"Посмотрим на первый столбец. Там цифры 3, 4, 3, 2, и только 3 повторяется дважды. Значит, код начинается с 3."},{"title":"Сравним остальные столбцы","text":"Во втором столбце дважды стоит 1, в третьем — 2, в четвёртом — 4. Так каждая цифра оказалась на нужном месте дважды. Код 3124."}],"keyNote":null},{"number":20,"title":"Два переворота карточки","question":"Карточку, изображенную справа, перевернули сначала через левый край, а потом — через верхний край. Что получилось?","options":[{"image":"assets/grades-2/2016/task-20-answer-1.svg","description":"Чёрный треугольник слева, маленький контурный треугольник сверху"},{"image":"assets/grades-2/2016/task-20-answer-2.svg","description":"Чёрный треугольник справа, маленький контурный треугольник сверху"},{"image":"assets/grades-2/2016/task-20-answer-3.svg","description":"Чёрный треугольник сверху, маленький контурный треугольник справа"},{"image":"assets/grades-2/2016/task-20-answer-4.svg","description":"Чёрный треугольник справа, маленький контурный треугольник снизу"},{"image":"assets/grades-2/2016/task-20-answer-5.svg","description":"Чёрный треугольник снизу, маленький контурный треугольник слева"}],"condition":{"src":"assets/grades-2/2016/task-20.svg","width":244,"height":238,"alt":"Справа квадратная карточка. Чёрный треугольник опирается на левый край, маленький контурный треугольник — на нижний. Стрелки показывают переворот влево, затем вверх."},"answer":1,"points":4,"review":[{"title":"Перевернём через левый край","text":"Левая и правая стороны поменяются местами. Чёрный треугольник окажется справа, а контурный пока останется у нижнего края."},{"title":"Перевернём через верхний край","text":"Теперь верх и низ поменяются местами. Контурный треугольник окажется сверху, чёрный останется справа. Это рисунок Б."}],"keyNote":null},{"number":21,"title":"Монеты в полоске клеток","question":"Джон нарисовал полоску из 11 клеток и укладывает 8 монет по одной в клетку так, чтобы между монетами не было пустых клеток. Это можно сделать разными способами, но есть клетки, в которых при любом способе будет лежать монета. Сколько таких клеток?","options":[{"text":"1"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":{"src":"assets/grades-2/2016/task-21.svg","width":550,"height":62,"alt":"Пустая полоска из одиннадцати клеток."},"answer":3,"points":5,"review":[{"title":"Сдвинем восемь монет к краям","text":"Без промежутков монеты можно положить от 1-й до 8-й клетки или сдвигать блок вправо, пока он не займёт места с 4-го по 11-е."},{"title":"Найдём общие клетки","text":"При обоих крайних положениях заняты клетки 4, 5, 6, 7 и 8. При промежуточном положении блок тоже проходит через все эти клетки. Их пять."}],"keyNote":null},{"number":22,"title":"Пирожки для внуков","question":"Бабушка раздала 10 пирожков своим пяти внукам. Каждому досталось не меньше одного пирожка. Что может быть верно?","options":[{"text":"Кто-то получил 6 пирожков, а кто-то — 2."},{"text":"Три внука получили по 3 пирожка."},{"text":"Два внука получили по 4 пирожка."},{"text":"Четыре внука получили по одному пирожку."},{"text":"Ровно четыре внука получили по 2 пирожка."}],"condition":null,"answer":3,"points":5,"review":[{"title":"Проверим, хватает ли пирожков","text":"Для шести и двух пирожков у двух внуков понадобится ещё по одному трём остальным, всего хотя бы 11. Три порции по три и две порции по четыре тоже требуют хотя бы 11, если учесть остальных."},{"title":"Проверим варианты с четырьмя внуками","text":"Если ровно четверо получили по два, пятому тоже досталось 10 − 8 = 2, и слово «ровно» неверно. А если четверым дать по одному, пятому можно дать шесть. Подходит Г."}],"keyNote":null},{"number":23,"title":"Узор на барабане","question":"На четырех из рисунков А – Д нарисован один и тот же барабан, а на одном — другой. На каком?","options":[{"image":"assets/grades-2/2016/task-23-answer-1.svg","description":"Чёрная полоса слева, широкая серая и светлая в тонкую косую полоску"},{"image":"assets/grades-2/2016/task-23-answer-2.svg","description":"Светлая полоса посередине, справа чёрная полоса с сеткой"},{"image":"assets/grades-2/2016/task-23-answer-3.svg","description":"Чёрная полоса слева, светлая в тонкую косую полоску и широкая серая"},{"image":"assets/grades-2/2016/task-23-answer-4.svg","description":"Чёрная полоса с сеткой слева, широкая серая и чёрная без рисунка справа"},{"image":"assets/grades-2/2016/task-23-answer-5.svg","description":"Узкая светлая штриховка слева, широкая серая, белая и узкая чёрная с сеткой справа"}],"condition":null,"answer":0,"points":5,"review":[{"title":"Восстановим порядок полос","text":"Поворот барабана открывает другой участок, но сохраняет порядок полос. По В, Д, Б и Г можно проследить круг: чёрная сплошная, тонкая штриховка, серая, белая, чёрная в сетку, ещё одна серая и снова чёрная сплошная."},{"title":"Найдём нарушение порядка","text":"В А после сплошной чёрной полосы идёт серая, а уже потом тонкая штриховка. В В чёрная и тонко штрихованная соседствуют сразу. Значит, на А другой барабан."}],"keyNote":null},{"number":24,"title":"Дата без повторов цифр","question":"Дату записывают восемью цифрами. Например, 25.06.1987 — 25 июня 1987 года. Заметим, что в записи этой даты ни одна цифра не повторяется дважды. Какими будут первые две цифры в записи следующей даты с таким же свойством?","options":[{"text":"08"},{"text":"12"},{"text":"17"},{"text":"23"},{"text":"25"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Проверим конец 1987 года","text":"После 25 июня оставшиеся числа месяца повторяют цифру 6, 7, 8, 9 или 0. В месяцах с июля по декабрь тоже повторится цифра из 1987 или внутри номера месяца."},{"title":"Отложим целые группы лет","text":"В 1988–1999 годах цифры года повторяются. В 2000–2099 годах уже заняты 2 и 0, а без них нельзя записать ни один месяц без повторов. В 2100–2199 заняты 2 и 1. Месяц должен взять 0, после чего число месяца могло бы начинаться только с 3, но 30 и 31 снова используют 0 или 1. В 2200–2299 повторяется 2."},{"title":"Найдём первый год после 2300","text":"В годах, начинающихся на 23, месяц берёт 0, а число месяца должно начинаться на 1. Поэтому две последние цифры года должны быть разными и не могут быть 0, 1, 2 или 3. Первый такой год — 2345."},{"title":"Подберём месяц и день","text":"Месяцы с января по май заняли бы цифру из года или цифру 1, нужную для дня. В июне 06 можно взять день 17: 17.06.2345. Меньшие дни на 1 повторили бы одну из уже использованных цифр. Первые две цифры — 17."}],"keyNote":null},{"number":25,"title":"Ребус про гнома и скалу","question":"В числовом ребусе ГНОМ + ГНОМ = СКАЛА разные буквы обозначают разные цифры. Какую цифру обозначает буква Г, если М = 3?","options":[{"text":"5"},{"text":"6"},{"text":"7"},{"text":"8"},{"text":"9"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Начнём с единиц","text":"Из М = 3 получаем А = 6. В сотнях снова выходит 6, поэтому из десятков ничего не переносили: удвоенная цифра с переносом была бы нечётной. Сотни — удвоенная Н, и Н = 8, так как цифра 3 уже занята М."},{"title":"Разберём тысячи","text":"От 8 + 8 = 16 переносится единица в тысячи. Чтобы получилась сумма из пяти знаков, первая цифра С равна 1, а Г может быть 5, 7 или 9: шестёрка и восьмёрка уже заняты. При 5 цифра К тоже будет 1, а при 9 цифра К тоже будет 9. Остаётся Г = 7."},{"title":"Проверим пример","text":"7823 + 7823 = 15646. Все разные буквы имеют разные цифры, и Г действительно равно 7."}],"keyNote":null}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  function shadeCells(step, frame) {
    if (step !== 2) return null;
    const alreadyShaded = [2, 4, 7, 9];
    const newlyShaded = [0, 1];
    const cells = Array.from({length: 12}, (_, index) => {
      const x = 90 + index % 4 * 42;
      const y = 20 + Math.floor(index / 4) * 42;
      const change = newlyShaded.indexOf(index);
      const opacity = alreadyShaded.includes(index) ? 1 : change < 0 ? 0 : visual.reveal(frame * 2 - change * .65);
      return `<rect x="${x}" y="${y}" width="42" height="42" fill="#fff"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="#202020" opacity="${opacity}"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="none" stroke="#202020" stroke-width="1.2"/>`;
    });
    return visual.svg(cells.join(''), 'В двух белых клетках верхней строки появляется чёрная заливка',
      '65 6 218 154', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame)
          : id === '2017-2' && number === 6 ? shadeCells(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

register((globalThis.KENGURU_ARCHIVE["2016-2"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2016] ?? []).find(edition => edition.id === "2016-2")), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
